import React, { useState, useMemo, useEffect } from "react";
import { TicketRecord } from "../types";
import { 
  ArrowUpDown, 
  Download, 
  Search, 
  ChevronLeft, 
  ChevronRight, 
  AlertTriangle, 
  FileSpreadsheet, 
  CheckCircle,
  HelpCircle
} from "lucide-react";
import * as XLSX from "xlsx";
import { TicketLink } from "./TicketLink";
import { isUnanswered, formatMinutes, statusColor } from "../utils/ticketHelpers";
import { zohoTicketUrl } from "../utils/zoho";

interface CriticalTicketsTableProps {
  filteredTickets: TicketRecord[];
}

type SortField = 
  | "ID de Ticket" 
  | "Nombre de Cuenta" 
  | "Asunto" 
  | "Prioridad (Ticket)" 
  | "Estado (Ticket)" 
  | "Propietario de Ticket" 
  | "Tiempo de primera respuesta en horario laboral"
  | "Hora de creación (Ticket)"
  | "Demora Calendario (Real)";

export function CriticalTicketsTable({ filteredTickets }: CriticalTicketsTableProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  // Sorting states. Default sorting: "Tiempo de primera respuesta en horario laboral" DESCENDING as requested!
  const [sortField, setSortField] = useState<SortField>("Tiempo de primera respuesta en horario laboral");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");

  // Handle priority ranking weight
  const getPriorityWeight = (priority: string) => {
    const p = (priority || "").toLowerCase();
    if (p === "crítica" || p === "critica") return 4;
    if (p === "alta") return 3;
    if (p === "media") return 2;
    if (p === "baja") return 1;
    return 0;
  };

  // Formatter for elapsed delay time in minutes, hours, and days
  const formatDetailedDelay = (minutes: number) => {
    if (!minutes || isNaN(minutes) || minutes <= 0) {
      return { raw: "0 min", human: "Atendido / Sin demora", isHigh: false };
    }

    const raw = `${minutes} min`;
    const days = Math.floor(minutes / 1440);
    const hours = Math.floor((minutes % 1440) / 60);
    const mins = Math.round(minutes % 60);

    const parts: string[] = [];
    if (days > 0) {
      parts.push(`${days} ${days === 1 ? 'día' : 'días'}`);
    }
    if (hours > 0) {
      parts.push(`${hours} h`);
    }
    if (mins > 0 || parts.length === 0) {
      parts.push(`${mins} min`);
    }

    return {
      raw,
      human: parts.join(", "),
      isHigh: minutes >= 60,
      isCritical: minutes >= 180
    };
  };

  // Function to calculate and format exact calendar delay between creation and response (or now)
  const formatCalendarDelay = (createdStr: string, respondedStr: string) => {
    if (!createdStr) {
      return { text: "N/D", isCritical: false, isHigh: false, minutes: 0, isAnswered: false };
    }

    const cleanedCreated = createdStr.replace(/-/g, "/");
    const createdDate = new Date(cleanedCreated);
    if (isNaN(createdDate.getTime())) {
      return { text: "Formato inválido", isCritical: false, isHigh: false, minutes: 0, isAnswered: false };
    }

    let endDate: Date;
    let isAnswered = true;
    if (respondedStr && respondedStr.trim() !== "") {
      const cleanedResponded = respondedStr.replace(/-/g, "/");
      endDate = new Date(cleanedResponded);
      if (isNaN(endDate.getTime())) {
        endDate = new Date(); // fallback
        isAnswered = false;
      }
    } else {
      endDate = new Date(); // Current live time
      isAnswered = false;
    }

    const diffMs = endDate.getTime() - createdDate.getTime();
    const diffMinutes = Math.max(0, Math.round(diffMs / 60000));

    if (diffMinutes === 0) {
      return { 
        text: isAnswered ? "Al instante (< 1m)" : "Creado ahora", 
        isCritical: false, 
        isHigh: false,
        minutes: 0,
        isAnswered 
      };
    }

    const days = Math.floor(diffMinutes / 1440);
    const hours = Math.floor((diffMinutes % 1440) / 60);
    const mins = diffMinutes % 60;

    const parts: string[] = [];
    if (days > 0) parts.push(`${days}d`);
    if (hours > 0) parts.push(`${hours}h`);
    if (mins > 0 || parts.length === 0) parts.push(`${mins}m`);

    const delayText = parts.join(" ");

    return {
      text: isAnswered ? `Atendido en ${delayText}` : `Espera: ${delayText}`,
      isCritical: !isAnswered && diffMinutes >= 180, // unanswered for more than 3 hours
      isHigh: diffMinutes >= 60,
      minutes: diffMinutes,
      isAnswered
    };
  };

  // Demora real: si no tiene respuesta, tiempo de espera desde la creación; si ya se respondió,
  // tiempo de primera respuesta en horario laboral.
  const realDelayMinutes = (t: TicketRecord) =>
    isUnanswered(t)
      ? formatCalendarDelay(t["Hora de creación (Ticket)"] || "", "").minutes
      : Number(t["Tiempo de primera respuesta en horario laboral"]) || 0;

  // Filter and sort tickets
  const processedTickets = useMemo(() => {
    // 1. Text search filter
    let results = filteredTickets.filter(t => {
      const q = searchQuery.toLowerCase();
      return (
        (t["ID de Ticket"] || "").toLowerCase().includes(q) ||
        (t["Nombre de Cuenta"] || "").toLowerCase().includes(q) ||
        (t["Asunto"] || "").toLowerCase().includes(q) ||
        (t["Propietario de Ticket"] || "").toLowerCase().includes(q) ||
        (t["Prioridad (Ticket)"] || "").toLowerCase().includes(q) ||
        (t["Estado (Ticket)"] || "").toLowerCase().includes(q) ||
        (t["Ingeniero de soporte asignado"] || "").toLowerCase().includes(q)
      );
    });

    // 2. Sort results
    results.sort((a, b) => {
      let valA: any;
      let valB: any;

      if (sortField === "Prioridad (Ticket)") {
        valA = getPriorityWeight(String(a["Prioridad (Ticket)"]));
        valB = getPriorityWeight(String(b["Prioridad (Ticket)"]));
      } 
      else if (sortField === "Tiempo de primera respuesta en horario laboral") {
        valA = Number(a["Tiempo de primera respuesta en horario laboral"]) || 0;
        valB = Number(b["Tiempo de primera respuesta en horario laboral"]) || 0;
      } 
      else if (sortField === "Hora de creación (Ticket)") {
        const timeA = a["Hora de creación (Ticket)"] ? new Date(String(a["Hora de creación (Ticket)"]).replace(/-/g, "/")).getTime() : 0;
        const timeB = b["Hora de creación (Ticket)"] ? new Date(String(b["Hora de creación (Ticket)"]).replace(/-/g, "/")).getTime() : 0;
        valA = isNaN(timeA) ? 0 : timeA;
        valB = isNaN(timeB) ? 0 : timeB;
      }
      else if (sortField === "Demora Calendario (Real)") {
        const delayA = realDelayMinutes(a);
        const delayB = realDelayMinutes(b);
        valA = delayA;
        valB = delayB;
      }
      else {
        valA = String(a[sortField] || "").toLowerCase();
        valB = String(b[sortField] || "").toLowerCase();
      }

      if (valA < valB) return sortDirection === "asc" ? -1 : 1;
      if (valA > valB) return sortDirection === "asc" ? 1 : -1;
      return 0;
    });

    return results;
  }, [filteredTickets, searchQuery, sortField, sortDirection]);

  // Al cambiar el filtro de propietario se vuelve a la primera página
  useEffect(() => { setCurrentPage(1); }, [filteredTickets]);

  // Paginated records
  const totalRecords = processedTickets.length;
  const totalPages = Math.ceil(totalRecords / pageSize) || 1;

  const paginatedTickets = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return processedTickets.slice(start, start + pageSize);
  }, [processedTickets, currentPage, pageSize]);

  // Triggered when clicking columns
  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("desc"); // Default to desc for new fields
    }
    setCurrentPage(1);
  };

  // Export visible/filtered table to CSV
  const handleExportCSV = () => {
    const headers = [
      "ID de Ticket",
      "Nombre de Cuenta",
      "Asunto",
      "Prioridad (Ticket)",
      "Estado (Ticket)",
      "Propietario de Ticket",
      "Tiempo de primera respuesta en horario laboral"
    ];

    const csvRows = [
      headers.join(","),
      ...processedTickets.map(t => [
        `"${String(t["ID de Ticket"] || "").replace(/"/g, '""')}"`,
        `"${String(t["Nombre de Cuenta"] || "").replace(/"/g, '""')}"`,
        `"${String(t["Asunto"] || "").replace(/"/g, '""')}"`,
        `"${String(t["Prioridad (Ticket)"] || "").replace(/"/g, '""')}"`,
        `"${String(t["Estado (Ticket)"] || "").replace(/"/g, '""')}"`,
        `"${String(t["Propietario de Ticket"] || "").replace(/"/g, '""')}"`,
        t["Tiempo de primera respuesta en horario laboral"] || 0
      ].join(","))
    ];

    const blob = new Blob([new Uint8Array([0xEF, 0xBB, 0xBF]), csvRows.join("\n")], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `casos_criticos_ecs_${new Date().toISOString().slice(0, 10)}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Export full ticket record dataset or filtered dataset to genuine .XLSX Excel sheet
  const handleExportExcel = () => {
    // Structure data exactly for Excel
    const dataToExport = processedTickets.map(t => ({
      "ID de Ticket": t["ID de Ticket"],
      "Enlace Zoho": zohoTicketUrl(t),
      "Nombre de Cuenta": t["Nombre de Cuenta"],
      "Asunto": t["Asunto"],
      "Prioridad": t["Prioridad (Ticket)"],
      "Estado": t["Estado (Ticket)"],
      "Propietario": t["Propietario de Ticket"],
      "Tiempo 1ª Respuesta (min)": Number(t["Tiempo de primera respuesta en horario laboral"]) || 0,
      "Clasificación": t["Clasificaciones"],
      "Ingeniero Asignado": t["Ingeniero de soporte asignado"],
      "SLA Vulneración": t["Tipo de vulneración del SLA"],
      "Total Horas Empleadas": Number(t["Tiempo total empleado"]) || 0
    }));

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Casos de Soporte");

    // Generate buffer and trigger download
    XLSX.writeFile(workbook, `Reporte_Soporte_ECS_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 shadow-xs overflow-hidden" id="critical-cases-panel">
      {/* Table Header Controls */}
      <div className="p-5 border-b border-gray-100 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-gray-50/50">
        <div>
          <h3 className="text-sm font-bold text-gray-900 flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-amber-500 animate-bounce" />
            Informe Detallado de Casos
          </h3>
          <p className="text-[11px] text-gray-500 mt-0.5">
            Todos los casos del filtro actual, ordenados por la mayor demora de primera respuesta. Clic en el ticket para abrirlo en Zoho Desk.
          </p>
        </div>

        {/* Search, Rows selection, and Export buttons */}
        <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
          {/* Dynamic Search */}
          <div className="relative shrink-0 w-full md:w-64">
            <span className="absolute inset-y-0 left-0 pl-2.5 flex items-center pointer-events-none">
              <Search className="h-3.5 w-3.5 text-gray-400" />
            </span>
            <input
              type="text"
              placeholder="Buscar en este informe..."
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setCurrentPage(1);
              }}
              className="block w-full pl-8 pr-3 py-1.5 border border-gray-300 rounded-lg text-xs focus:ring-[#005bbf] focus:border-[#005bbf]"
            />
          </div>

          {/* Export to CSV */}
          <button
            onClick={handleExportCSV}
            disabled={totalRecords === 0}
            className="inline-flex items-center gap-1 px-2.5 py-1.5 border border-gray-300 rounded-lg text-xs font-semibold text-gray-700 bg-white hover:bg-gray-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            title="Exportar a archivo CSV plano"
          >
            <Download className="w-3.5 h-3.5" />
            CSV
          </button>

          {/* Export to genuine Excel */}
          <button
            onClick={handleExportExcel}
            disabled={totalRecords === 0}
            className="inline-flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-white bg-emerald-600 hover:bg-emerald-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            title="Exportar reporte estructurado de Excel (.xlsx)"
          >
            <FileSpreadsheet className="w-3.5 h-3.5" />
            Excel
          </button>
        </div>
      </div>

      {/* Actual Data Table */}
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200 text-left text-xs">
          <thead className="bg-gray-50 text-gray-600 font-semibold uppercase tracking-wider text-[10px]">
            <tr>
              <th 
                scope="col" 
                onClick={() => handleSort("ID de Ticket")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none"
              >
                <div className="flex items-center gap-1">
                  ID de Ticket
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Nombre de Cuenta")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none"
              >
                <div className="flex items-center gap-1">
                  Nombre de Cuenta
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Asunto")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none w-1/4"
              >
                <div className="flex items-center gap-1">
                  Asunto
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Prioridad (Ticket)")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none text-center"
              >
                <div className="flex items-center justify-center gap-1">
                  Prioridad
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Estado (Ticket)")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none text-center"
              >
                <div className="flex items-center justify-center gap-1">
                  Estado
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Propietario de Ticket")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none"
              >
                <div className="flex items-center gap-1">
                  Propietario
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Hora de creación (Ticket)")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none bg-slate-100/30"
              >
                <div className="flex items-center gap-1">
                  Fechas (Creación / Respuesta)
                  <ArrowUpDown className="w-3 h-3 text-gray-400 group-hover:text-gray-700" />
                </div>
              </th>
              <th 
                scope="col" 
                onClick={() => handleSort("Demora Calendario (Real)")}
                className="px-4 py-3 cursor-pointer hover:bg-gray-100 transition-colors group select-none text-right bg-indigo-50/40 text-indigo-800"
              >
                <div className="flex items-center justify-end gap-1">
                  Demora Real
                  <ArrowUpDown className="w-3 h-3 text-indigo-500" />
                </div>
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-150">
            {paginatedTickets.length === 0 ? (
              <tr>
                <td colSpan={8} className="px-4 py-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center space-y-2">
                    <HelpCircle className="w-8 h-8 text-gray-300" />
                    <span>No se encontraron registros que coincidan con la búsqueda.</span>
                  </div>
                </td>
              </tr>
            ) : (
              paginatedTickets.map((ticket, index) => {
                const priorityLower = (ticket["Prioridad (Ticket)"] || "").toLowerCase();
                const statusLower = (ticket["Estado (Ticket)"] || "").toLowerCase();

                // Styling priorities
                let priorityBadge = "bg-gray-100 text-gray-700";
                if (priorityLower === "crítica" || priorityLower === "critica") {
                  priorityBadge = "bg-rose-100 text-rose-800 font-extrabold border border-rose-200";
                } else if (priorityLower === "alta") {
                  priorityBadge = "bg-amber-100 text-amber-800 font-semibold border border-amber-200";
                } else if (priorityLower === "media") {
                  priorityBadge = "bg-blue-50 text-blue-700 border border-blue-100";
                } else if (priorityLower === "baja") {
                  priorityBadge = "bg-slate-100 text-slate-600";
                }

                // Styling statuses
                let statusBadge = "bg-gray-100 text-gray-600";
                if (statusLower === "abierto") {
                  statusBadge = "bg-rose-50 text-rose-700 font-semibold border border-rose-100 animate-pulse";
                } else if (statusLower === "en progreso") {
                  statusBadge = "bg-amber-50 text-amber-800 border border-amber-100";
                } else if (statusLower === "pendiente") {
                  statusBadge = "bg-blue-50 text-blue-700 border border-blue-100";
                } else if (statusLower === "cerrado") {
                  statusBadge = "bg-emerald-50 text-emerald-700 border border-emerald-100";
                }

                // First response highlight if high
                const minutesVal = Number(ticket["Tiempo de primera respuesta en horario laboral"]) || 0;
                const delayInfo = formatDetailedDelay(minutesVal);
                let responseColor = "text-gray-900";
                if (minutesVal >= 180) {
                  responseColor = "text-rose-700 font-extrabold";
                } else if (minutesVal >= 60) {
                  responseColor = "text-amber-700 font-bold";
                }

                // Calculate the real elapsed calendar time
                const unansweredRow = isUnanswered(ticket);
                const calDelay = unansweredRow
                  ? formatCalendarDelay(ticket["Hora de creación (Ticket)"] || "", "")
                  : {
                      text: `1ª rpta: ${formatMinutes(minutesVal)} (lab.)`,
                      isCritical: false,
                      isHigh: minutesVal >= 60 * 24,
                      minutes: minutesVal,
                      isAnswered: true,
                    };

                let calBadgeColor = "text-gray-700 bg-gray-50 border border-gray-150";
                if (calDelay.isCritical) {
                  calBadgeColor = "text-rose-700 bg-rose-50 border border-rose-200 font-extrabold";
                } else if (calDelay.isHigh) {
                  calBadgeColor = "text-amber-700 bg-amber-50 border border-amber-200 font-bold";
                } else if (calDelay.isAnswered) {
                  calBadgeColor = "text-emerald-700 bg-emerald-50/60 border border-emerald-200 font-semibold";
                }

                return (
                  <tr 
                    key={ticket["ID de Ticket"] + "-" + index}
                    className="hover:bg-slate-50/70 transition-colors"
                  >
                    {/* ID */}
                    <td className="px-4 py-2.5 text-xs text-[#005bbf] whitespace-nowrap">
                      <TicketLink ticket={ticket} />
                    </td>

                    {/* Nombre Cuenta */}
                    <td className="px-4 py-2.5 font-semibold text-gray-900 truncate max-w-[140px]" title={ticket["Nombre de Cuenta"]}>
                      {ticket["Nombre de Cuenta"]}
                    </td>

                    {/* Asunto */}
                    <td className="px-4 py-2.5 text-gray-700 truncate max-w-xs" title={ticket["Asunto"]}>
                      <a href={zohoTicketUrl(ticket)} target="_blank" rel="noopener noreferrer" className="hover:text-[#005bbf] hover:underline">
                        {ticket["Asunto"]}
                      </a>
                    </td>

                    {/* Prioridad */}
                    <td className="px-4 py-2.5 text-center whitespace-nowrap">
                      <span className={`inline-flex px-2 py-0.5 rounded-full text-[10px] uppercase ${priorityBadge}`}>
                        {ticket["Prioridad (Ticket)"]}
                      </span>
                    </td>

                    {/* Estado */}
                    <td className="px-4 py-2.5 text-center whitespace-nowrap">
                      <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] uppercase ${statusBadge}`}>
                        <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: statusColor(ticket["Estado (Ticket)"] || "") }} />
                        {ticket["Estado (Ticket)"]}
                      </span>
                    </td>

                    {/* Propietario */}
                    <td className="px-4 py-2.5 text-gray-600 whitespace-nowrap">
                      {ticket["Propietario de Ticket"]}
                    </td>

                    {/* Fechas de Registro */}
                    <td className="px-4 py-2.5 text-gray-600 bg-slate-150/10">
                      <div className="flex flex-col text-[11px] space-y-0.5">
                        <span className="text-gray-500 font-medium">
                          <strong className="text-gray-700">Creado:</strong> {ticket["Hora de creación (Ticket)"] || "N/D"}
                        </span>
                        {!isUnanswered(ticket) ? (
                          <span className="text-emerald-600 font-semibold">
                            <strong className="text-emerald-700">Últ. rpta agente:</strong> {ticket["Tiempo de respuesta del agente"] || `${ticket["Número de respuestas"]} respuestas`}
                          </span>
                        ) : (
                          <span className="text-rose-500 font-bold animate-pulse">
                            🚨 Sin primera respuesta
                          </span>
                        )}
                      </div>
                    </td>

                    {/* Demora Calendario (Real) */}
                    <td className="px-4 py-2.5 text-right font-sans text-xs bg-indigo-50/10">
                      <div className="flex flex-col items-end">
                        <span className={`inline-flex px-2 py-1 rounded text-xs ${calBadgeColor}`}>
                          {calDelay.text}
                        </span>
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="p-4 border-t border-gray-150 flex flex-col sm:flex-row items-center justify-between gap-4 bg-gray-50/30">
        <div className="text-xs text-gray-500">
          Mostrando <span className="font-semibold text-gray-800">
            {totalRecords > 0 ? (currentPage - 1) * pageSize + 1 : 0}
          </span> a <span className="font-semibold text-gray-800">
            {Math.min(currentPage * pageSize, totalRecords)}
          </span> de <span className="font-semibold text-gray-800">{totalRecords}</span> registros 
          {searchQuery && ` (filtrado de ${filteredTickets.length} totales)`}
        </div>

        <div className="flex items-center gap-4">
          {/* Rows per page selector */}
          <div className="flex items-center gap-1.5 text-xs text-gray-500">
            <span>Filas por página:</span>
            <select
              value={pageSize}
              onChange={(e) => {
                setPageSize(Number(e.target.value));
                setCurrentPage(1);
              }}
              className="border border-gray-300 rounded px-1.5 py-1 text-xs focus:ring-[#005bbf] focus:border-[#005bbf]"
            >
              {[5, 10, 20, 50].map(size => (
                <option key={size} value={size}>{size}</option>
              ))}
            </select>
          </div>

          {/* Navigation Controls */}
          <div className="flex items-center gap-1">
            <button
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="p-1 rounded-md border border-gray-200 bg-white text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-xs text-gray-600 font-semibold min-w-[50px] text-center">
              {currentPage} / {totalPages}
            </span>
            <button
              onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className="p-1 rounded-md border border-gray-200 bg-white text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

src/components/DashboardCharts.tsx:
import React, { useEffect, useMemo, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from "recharts";
import { TicketRecord } from "../types";
import { Selection } from "../utils/selection";
import { TicketLink } from "./TicketLink";
import { ageDays, classificationOf, isClosed, isCriticalOrHigh, isUnanswered } from "../utils/ticketHelpers";
import * as XLSX from "xlsx";
import { 
  ShieldAlert, 
  BarChart3, 
  PieChartIcon, 
  Hourglass, 
  ListCollapse, 
  CheckCircle,
  X,
  Building2,
  AlertTriangle,
  Clock,
  ExternalLink,
  ChevronRight,
  Download,
  FileSpreadsheet
} from "lucide-react";

interface DashboardChartsProps {
  filteredTickets: TicketRecord[];
  onSelect?: (s: Selection) => void;
}

/** Crítico/alto, abierto y sin ninguna respuesta (regla única compartida con KPIs y detalle). */
const isCriticalUnanswered = (t: TicketRecord) => isCriticalOrHigh(t) && !isClosed(t) && isUnanswered(t);

export function DashboardCharts({ filteredTickets, onSelect }: DashboardChartsProps) {
  const [selectedAccount, setSelectedAccount] = useState<string | null>(null);
  const [detailTab, setDetailTab] = useState<"unanswered" | "all">("unanswered");

  // Helper function to calculate exact calendar delay
  const calculateCalendarDelay = (createdStr: string, respondedStr: string) => {
    if (!createdStr) return { text: "N/D", minutes: 0 };
    const createdDate = new Date(createdStr.replace(/-/g, "/"));
    if (isNaN(createdDate.getTime())) return { text: "Inválido", minutes: 0 };

    let endDate = new Date();
    let isAnswered = false;
    if (respondedStr && respondedStr.trim() !== "") {
      const respDate = new Date(respondedStr.replace(/-/g, "/"));
      if (!isNaN(respDate.getTime())) {
        endDate = respDate;
        isAnswered = true;
      }
    }

    const diffMs = endDate.getTime() - createdDate.getTime();
    const diffMinutes = Math.max(0, Math.round(diffMs / 60000));

    if (diffMinutes === 0) return { text: isAnswered ? "Al instante" : "Creado ahora", minutes: 0 };

    const days = Math.floor(diffMinutes / 1440);
    const hours = Math.floor((diffMinutes % 1440) / 60);
    const mins = diffMinutes % 60;

    const parts = [];
    if (days > 0) parts.push(`${days}d`);
    if (hours > 0) parts.push(`${hours}h`);
    if (mins > 0 || parts.length === 0) parts.push(`${mins}m`);

    return {
      text: isAnswered ? `Atendido en ${parts.join(" ")}` : `Espera: ${parts.join(" ")}`,
      minutes: diffMinutes,
      isAnswered
    };
  };

  // 1. Volume by Account ("Volumen por Cliente")
  const volumeByAccountData = useMemo(() => {
    const counts: Record<string, { total: number; open: number }> = {};

    filteredTickets.forEach(t => {
      const account = t["Nombre de Cuenta"] || "Sin Cuenta";
      const isOpen = !isClosed(t);

      if (!counts[account]) {
        counts[account] = { total: 0, open: 0 };
      }
      counts[account].total += 1;
      if (isOpen) {
        counts[account].open += 1;
      }
    });

    return Object.entries(counts)
      .map(([name, stats]) => ({
        name,
        "Casos Totales": stats.total,
        "Casos Abiertos": stats.open
      }))
      .sort((a, b) => b["Casos Totales"] - a["Casos Totales"])
      .slice(0, 8); // Top 8 accounts
  }, [filteredTickets]);

  // 2. Critical/High Priority Unanswered by Account ("Criticidad por Cliente")
  // High/Critical priority cases that are unanswered (no responses, no response date, no agent time) and status !== Closed/Solved
  const criticalUnansweredByAccount = useMemo(() => {
    const counts: Record<string, number> = {};

    filteredTickets.forEach(t => {
      if (isCriticalUnanswered(t)) {
        const account = t["Nombre de Cuenta"] || "Sin Cuenta";
        counts[account] = (counts[account] || 0) + 1;
      }
    });

    return Object.entries(counts)
      .map(([name, count]) => ({
        name,
        "Casos Críticos Sin Respuesta": count
      }))
      .sort((a, b) => b["Casos Críticos Sin Respuesta"] - a["Casos Críticos Sin Respuesta"])
      .slice(0, 8);
  }, [filteredTickets]);

  // 3. Distribution of Categories ("Distribución por Clasificación")
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredTickets.forEach(t => {
      const cat = classificationOf(t);
      counts[cat] = (counts[cat] || 0) + 1;
    });

    const colors = [
      "#005bbf", // primary blue
      "#f2994a", // orange accent
      "#3b82f6", // light blue
      "#10b981", // emerald green
      "#8b5cf6", // violet
      "#f59e0b", // amber
      "#ec4899", // pink
      "#6b7280"  // gray
    ];

    return Object.entries(counts)
      .map(([name, count], index) => ({
        name,
        value: count,
        color: colors[index % colors.length]
      }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 6);
  }, [filteredTickets]);

  // 4. Overdue aging historical alert list ("Casos sin Atender Históricos")
  // Tickets that have "Número de respuestas" = 0, status is NOT Cerrado, sorted descending by creation time / or first response minutes.
  const topAgingTickets = useMemo(() => {
    return filteredTickets
      .filter(t => !isClosed(t) && isUnanswered(t))
      .map(t => {
        return {
          ticket: t,
          id: t["ID de Ticket"],
          account: t["Nombre de Cuenta"],
          subject: t["Asunto"],
          priority: t["Prioridad (Ticket)"],
          status: t["Estado (Ticket)"],
          owner: t["Propietario de Ticket"],
          engineer: t["Ingeniero de soporte asignado"],
          created: t["Hora de creación (Ticket)"],
          // Días de espera desde la creación (el caso aún no tiene respuesta)
          delay: Math.floor(ageDays(t) ?? 0)
        };
      })
      .sort((a, b) => b.delay - a.delay); // Mayor espera primero
  }, [filteredTickets]);

  // Export the full list of historical unattended cases to a genuine .XLSX Excel sheet
  const handleExportAgingExcel = () => {
    const dataToExport = topAgingTickets.map(t => ({
      "ID de Ticket": t.id,
      "Nombre de Cuenta": t.account,
      "Asunto": t.subject,
      "Prioridad": t.priority,
      "Estado": t.status,
      "Propietario": t.owner,
      "Ingeniero Asignado": t.engineer,
      "Fecha de Creación": t.created,
      "Días de espera sin respuesta": t.delay
    }));

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Casos Históricos Sin Atender");

    XLSX.writeFile(workbook, `Casos_Historicos_Sin_Atender_ECS_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  // Filter all tickets for selected account
  const accountAllTickets = useMemo(() => {
    if (!selectedAccount) return [];
    return filteredTickets.filter(t => (t["Nombre de Cuenta"] || "Sin Cuenta") === selectedAccount);
  }, [filteredTickets, selectedAccount]);

  // Filter critical/high priority unanswered for selected account
  const accountCriticalUnansweredTickets = useMemo(() => {
    if (!selectedAccount) return [];
    return accountAllTickets.filter(isCriticalUnanswered);
  }, [accountAllTickets, selectedAccount]);

  // Si el filtro de propietario deja al cliente seleccionado sin casos, se cierra el detalle
  useEffect(() => {
    if (selectedAccount && accountAllTickets.length === 0) setSelectedAccount(null);
  }, [selectedAccount, accountAllTickets.length]);

  if (filteredTickets.length === 0) {
    return (
      <div className="bg-white border border-gray-200 rounded-xl p-8 text-center text-gray-500 shadow-xs">
        <div className="flex flex-col items-center justify-center space-y-2">
          <BarChart3 className="w-12 h-12 text-gray-300 animate-pulse" />
          <p className="text-sm font-semibold text-gray-700">Sin datos de gráficos para mostrar</p>
          <p className="text-xs text-gray-400">Selecciona propietarios de ticket o carga un archivo nuevo para visualizar los gráficos.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Visual Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Chart A.1: Volumen de Casos por Cliente */}
        <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-xs relative">
          <div className="flex items-start justify-between mb-4 pb-2 border-b border-gray-100">
            <div>
              <div className="flex items-center gap-2">
                <div className="p-1.5 bg-blue-50 text-[#005bbf] rounded">
                  <BarChart3 className="w-4 h-4" />
                </div>
                <h3 className="text-xs font-bold text-gray-900 uppercase tracking-wider">
                  Volumen de Casos por Cliente (Top 8)
                </h3>
              </div>
              <p className="text-[10px] text-gray-400 mt-1">Total de casos vs Casos aún abiertos</p>
            </div>
            <div className="text-right">
              <span className="inline-flex px-1.5 py-0.5 text-[9px] font-semibold bg-blue-50 text-blue-700 rounded-md border border-blue-100 animate-pulse">
                🖱️ Clic para filtrar
              </span>
            </div>
          </div>

          <div className="h-72 w-full">
            {volumeByAccountData.length === 0 ? (
              <div className="h-full flex items-center justify-center text-xs text-gray-400">Sin datos</div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart 
                  data={volumeByAccountData} 
                  margin={{ top: 10, right: 10, left: -20, bottom: 5 }}
                  onClick={(state: any) => {
                    if (state && state.activeLabel) {
                      setSelectedAccount(state.activeLabel);
                      setDetailTab("all");
                    } else if (state && state.activePayload && state.activePayload[0]) {
                      setSelectedAccount(state.activePayload[0].payload.name);
                      setDetailTab("all");
                    }
                  }}
                  style={{ cursor: "pointer" }}
                >
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f3f5" />
                  <XAxis dataKey="name" tick={{ fontSize: 9 }} stroke="#888888" tickLine={false} />
                  <YAxis tick={{ fontSize: 9 }} stroke="#888888" tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: "#1e293b", color: "#fff", borderRadius: "8px", fontSize: "11px" }}
                    itemStyle={{ color: "#fff" }}
                  />
                  <Legend wrapperStyle={{ fontSize: "10px" }} />
                  <Bar dataKey="Casos Totales" fill="#005bbf" radius={[4, 4, 0, 0]} barSize={24} />
                  <Bar dataKey="Casos Abiertos" fill="#f2994a" radius={[4, 4, 0, 0]} barSize={24} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>

        {/* Chart A.2: Criticidad por Cliente (Casos Críticos Sin Respuesta) */}
        <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-xs relative">
          <div className="flex items-start justify-between mb-4 pb-2 border-b border-gray-100">
            <div>
              <div className="flex items-center gap-2">
                <div className="p-1.5 bg-rose-50 text-rose-600 rounded">
                  <ShieldAlert className="w-4 h-4" />
                </div>
                <h3 className="text-xs font-bold text-gray-900 uppercase tracking-wider">
                  Criticidad por Cliente (Casos Críticos/Altos Sin Responder)
                </h3>
              </div>
              <p className="text-[10px] text-gray-400 mt-1">Casos críticos o de alta prioridad sin ninguna respuesta inicial</p>
            </div>
            <div className="text-right">
              <span className="inline-flex px-1.5 py-0.5 text-[9px] font-semibold bg-rose-50 text-rose-700 rounded-md border border-rose-100 animate-pulse">
                🚨 Clic para auditar
              </span>
            </div>
          </div>

          <div className="h-72 w-full">
            {criticalUnansweredByAccount.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-xs text-gray-400 p-4 text-center">
                <CheckCircle className="w-8 h-8 text-emerald-500 mb-1" />
                <span className="font-semibold text-gray-700">¡Excelente!</span>
                <span>No hay casos críticos sin respuesta inicial en este grupo.</span>
              </div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart 
                  data={criticalUnansweredByAccount} 
                  margin={{ top: 10, right: 10, left: -20, bottom: 5 }}
                  onClick={(state: any) => {
                    if (state && state.activeLabel) {
                      setSelectedAccount(state.activeLabel);
                      setDetailTab("unanswered");
                    } else if (state && state.activePayload && state.activePayload[0]) {
                      setSelectedAccount(state.activePayload[0].payload.name);
                      setDetailTab("unanswered");
                    }
                  }}
                  style={{ cursor: "pointer" }}
                >
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f3f5" />
                  <XAxis dataKey="name" tick={{ fontSize: 9 }} stroke="#888888" tickLine={false} />
                  <YAxis tick={{ fontSize: 9 }} stroke="#888888" tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: "#1e293b", color: "#fff", borderRadius: "8px", fontSize: "11px" }}
                    itemStyle={{ color: "#fff" }}
                  />
                  <Bar dataKey="Casos Críticos Sin Respuesta" fill="#dc2626" radius={[4, 4, 0, 0]} barSize={32} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>
      </div>

      {/* Interactive Detail Inspector Drawer */}
      {selectedAccount && (
        <div className="bg-slate-900 text-white rounded-xl border border-slate-800 shadow-lg p-5 sm:p-6 space-y-4 animate-fade-in" id="chart-drilldown-panel">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-800 pb-3">
            <div className="flex items-center gap-2">
              <div className="p-2 bg-slate-800 text-amber-400 rounded-lg">
                <Building2 className="w-5 h-5" />
              </div>
              <div>
                <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Inspección de Cliente Seleccionado</span>
                <h4 className="text-base font-black tracking-tight text-white">{selectedAccount}</h4>
              </div>
            </div>
            <button 
              onClick={() => setSelectedAccount(null)}
              className="p-1.5 hover:bg-slate-800 text-slate-400 hover:text-white rounded-lg transition-colors cursor-pointer"
              title="Cerrar detalle"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Quick Metrics */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="bg-slate-950 p-3 rounded-lg border border-slate-850">
              <div className="text-[10px] font-bold text-slate-400 uppercase">Casos Totales</div>
              <div className="text-xl font-mono font-black text-blue-400 mt-1">{accountAllTickets.length}</div>
            </div>
            <div className="bg-slate-950 p-3 rounded-lg border border-slate-850 border-l-4 border-l-rose-500">
              <div className="text-[10px] font-bold text-slate-400 uppercase">Críticos / Altos sin Responder</div>
              <div className="text-xl font-mono font-black text-rose-400 mt-1">{accountCriticalUnansweredTickets.length}</div>
            </div>
            <div className="bg-slate-950 p-3 rounded-lg border border-slate-850">
              <div className="text-[10px] font-bold text-slate-400 uppercase">Porcentaje de Atención</div>
              <div className="text-xl font-mono font-black text-emerald-400 mt-1">
                {accountAllTickets.length > 0 
                  ? Math.round(((accountAllTickets.length - accountCriticalUnansweredTickets.length) / accountAllTickets.length) * 100) 
                  : 100}%
              </div>
            </div>
          </div>

          {/* Tab Selection */}
          <div className="flex border-b border-slate-800">
            <button
              onClick={() => setDetailTab("unanswered")}
              className={`px-4 py-2 text-xs font-bold transition-colors border-b-2 flex items-center gap-1.5 cursor-pointer ${
                detailTab === "unanswered" 
                  ? "border-rose-500 text-rose-400 bg-rose-500/5" 
                  : "border-transparent text-slate-400 hover:text-white"
              }`}
            >
              <AlertTriangle className="w-3.5 h-3.5" />
              Críticos Sin Responder ({accountCriticalUnansweredTickets.length})
            </button>
            <button
              onClick={() => setDetailTab("all")}
              className={`px-4 py-2 text-xs font-bold transition-colors border-b-2 flex items-center gap-1.5 cursor-pointer ${
                detailTab === "all" 
                  ? "border-blue-500 text-blue-400 bg-blue-500/5" 
                  : "border-transparent text-slate-400 hover:text-white"
              }`}
            >
              <ListCollapse className="w-3.5 h-3.5" />
              Todos los Casos de este Cliente ({accountAllTickets.length})
            </button>
          </div>

          {/* List of Tickets */}
          <div className="overflow-x-auto rounded-lg border border-slate-800">
            {detailTab === "unanswered" && accountCriticalUnansweredTickets.length === 0 ? (
              <div className="py-8 text-center text-slate-400 text-xs flex flex-col items-center justify-center">
                <CheckCircle className="w-8 h-8 text-emerald-500 mb-1.5" />
                <span className="font-bold text-white">¡No hay casos críticos sin respuesta!</span>
                <span>Todos los incidentes críticos de este cliente tienen una interacción registrada.</span>
              </div>
            ) : detailTab === "all" && accountAllTickets.length === 0 ? (
              <div className="py-8 text-center text-slate-400 text-xs">No hay tickets registrados para este cliente.</div>
            ) : (
              <table className="w-full text-left border-collapse text-xs">
                <thead>
                  <tr className="bg-slate-950/60 text-slate-400 border-b border-slate-800">
                    <th className="p-3 font-semibold">ID</th>
                    <th className="p-3 font-semibold w-2/5">Asunto</th>
                    <th className="p-3 font-semibold">Prioridad</th>
                    <th className="p-3 font-semibold">Estado</th>
                    <th className="p-3 font-semibold">Asignado</th>
                    <th className="p-3 font-semibold text-right">Demora de Primera Respuesta</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-850">
                  {(detailTab === "unanswered" ? accountCriticalUnansweredTickets : accountAllTickets).map((t, idx) => {
                    const priorityLower = (t["Prioridad (Ticket)"] || "").toLowerCase();
                    const statusLower = (t["Estado (Ticket)"] || "").toLowerCase();
                    const isCritical = priorityLower.includes("crít") || priorityLower.includes("crit");

                    let prioBadge = "bg-slate-800 text-slate-300";
                    if (isCritical) {
                      prioBadge = "bg-rose-950/80 text-rose-400 font-extrabold border border-rose-900";
                    } else if (priorityLower.includes("alt")) {
                      prioBadge = "bg-amber-950/80 text-amber-400 font-bold border border-amber-900";
                    }

                    let statBadge = "bg-slate-850 text-slate-400";
                    if (statusLower === "abierto") {
                      statBadge = "bg-rose-950/30 text-rose-400 border border-rose-900/40 animate-pulse";
                    } else if (statusLower === "en progreso") {
                      statBadge = "bg-amber-950/30 text-amber-400 border border-amber-900/40";
                    } else if (statusLower === "cerrado") {
                      statBadge = "bg-emerald-950/30 text-emerald-400 border border-emerald-900/40";
                    }

                    const hasResponseDate = (t["Hora de responder"] || "").trim() !== "";
                    const unanswered = isUnanswered(t);

                    const minutesVal = Number(t["Tiempo de primera respuesta en horario laboral"]) || 0;
                    const calDelay = calculateCalendarDelay(t["Hora de creación (Ticket)"] || "", "");

                    return (
                      <tr key={idx} className="hover:bg-slate-850/50 transition-colors">
                        <td className="p-3 whitespace-nowrap"><TicketLink ticket={t} className="text-blue-400" /></td>
                        <td className="p-3">
                          <div className="font-semibold text-slate-100">{t["Asunto"]}</div>
                          <div className="text-[10px] text-slate-400 mt-0.5 flex flex-col sm:flex-row sm:items-center gap-1.5 sm:gap-3">
                            <span>Creado: {t["Hora de creación (Ticket)"] || "N/D"}</span>
                            {hasResponseDate && <span>Vence: {t["Hora de responder"]}</span>}
                          </div>
                        </td>
                        <td className="p-3">
                          <span className={`px-1.5 py-0.5 rounded text-[10px] ${prioBadge}`}>
                            {t["Prioridad (Ticket)"]}
                          </span>
                        </td>
                        <td className="p-3">
                          <span className={`px-1.5 py-0.5 rounded text-[10px] ${statBadge}`}>
                            {t["Estado (Ticket)"]}
                          </span>
                        </td>
                        <td className="p-3 text-slate-300 font-medium">{t["Ingeniero de soporte asignado"] || "Sin Asignar"}</td>
                        <td className="p-3 text-right">
                          {unanswered ? (
                            <div className="font-extrabold text-rose-500 animate-pulse">🚨 Sin 1ª Respuesta</div>
                          ) : (
                            <div className="font-bold text-emerald-400">
                              {minutesVal > 0 ? `${minutesVal} min (Lab)` : "Atendido"}
                            </div>
                          )}
                          {unanswered && <div className="text-[10px] text-slate-400 mt-0.5">{calDelay.text}</div>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}

      {/* Second row: Categories distribution and Historical Aging alerts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Chart A.3: Categorías de Tickets */}
        <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-xs lg:col-span-1">
