                    onClick={(r: any) => { const d = P(r); return d[k] && onSelect({
                      title: `Sin actividad ${d.name} · ${k}`,
                      criteria: [{ dimension: "inactivity", value: d.name }, { dimension: "lastFrom", value: k }],
                    }); }} />
                ))}
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>
      )}
    </div>
  );
}

