import React, { useRef, useState } from "react";
import { UploadCloud, FileSpreadsheet, Download, AlertCircle, CheckCircle } from "lucide-react";
import { parseFile, downloadSampleCSV } from "../utils/parser";
import { TicketRecord } from "../types";

interface UploadZoneProps {
  onDataLoaded: (data: TicketRecord[]) => void;
  onClearData: () => void;
  dataCount: number;
}

export function UploadZone({ onDataLoaded, onClearData, dataCount }: UploadZoneProps) {
  const [isDragActive, setIsDragActive] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setIsDragActive(true);
    } else if (e.type === "dragleave") {
      setIsDragActive(false);
    }
  };

  const processFile = async (file: File) => {
    // Basic file validation
    const fileExt = file.name.split(".").pop()?.toLowerCase();
    if (fileExt !== "xlsx" && fileExt !== "csv" && fileExt !== "xls") {
      setError("Solo se admiten archivos Excel (.xlsx, .xls) o de valores separados por comas (.csv).");
      return;
    }

    setLoading(true);
    setError(null);
    setSuccessMsg(null);

    try {
      const parsedData = await parseFile(file);
      onDataLoaded(parsedData);
      setSuccessMsg(`¡Cargado con éxito! Se procesaron ${parsedData.length} registros del archivo "${file.name}". Se ha sobrescrito la base de datos anterior.`);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Error al analizar el archivo. Asegúrate de que las columnas coincidan exactamente con la plantilla.");
    } finally {
      setLoading(false);
      setIsDragActive(false);
    }
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      await processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileInputChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      await processFile(e.target.files[0]);
    }
  };

  const onButtonClick = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-xs">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between mb-4 pb-4 border-b border-gray-100 gap-4">
        <div>
          <h2 className="text-base font-bold text-gray-900 flex items-center gap-2">
            <FileSpreadsheet className="w-5 h-5 text-[#005bbf]" />
            Carga de Archivo de Datos de Soporte
          </h2>
          <p className="text-xs text-gray-500 mt-1">
            Sube un archivo Excel (.xlsx, .xls) o CSV con el formato corporativo. Cada nueva carga eliminará y reemplazará la información actual.
          </p>
        </div>

        <div className="flex flex-wrap gap-2 shrink-0">
          <button
            onClick={downloadSampleCSV}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-[#005bbf] bg-[#005bbf]/10 hover:bg-[#005bbf]/20 transition-colors"
          >
            <Download className="w-3.5 h-3.5" />
            Descargar Plantilla CSV
          </button>
          {dataCount > 0 && (
            <button
              onClick={onClearData}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-rose-600 bg-rose-50 hover:bg-rose-100 transition-colors"
            >
              Restablecer Datos
            </button>
          )}
        </div>
      </div>

      {/* Drag & Drop Zone */}
      <div
        onDragEnter={handleDrag}
        onDragOver={handleDrag}
        onDragLeave={handleDrag}
        onDrop={handleDrop}
        onClick={onButtonClick}
        className={`relative border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center cursor-pointer transition-all duration-300 ${
          isDragActive
            ? "border-[#005bbf] bg-[#005bbf]/5 scale-[0.995]"
            : "border-gray-300 hover:border-[#005bbf] hover:bg-gray-50"
        }`}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".xlsx,.xls,.csv"
          className="hidden"
          onChange={handleFileInputChange}
          disabled={loading}
        />

        {loading ? (
          <div className="flex flex-col items-center space-y-3">
            <div className="w-10 h-10 border-4 border-t-[#005bbf] border-gray-200 rounded-full animate-spin"></div>
            <p className="text-sm font-semibold text-gray-700">Analizando registros y estructurando bases de datos...</p>
            <p className="text-xs text-gray-400">Por favor, espera un momento.</p>
          </div>
        ) : (
          <div className="space-y-3">
            <div className="mx-auto w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center text-[#005bbf]">
              <UploadCloud className="w-6 h-6" />
            </div>
            <div>
              <p className="text-sm font-semibold text-gray-700">
                Arrastra tu archivo aquí o <span className="text-[#005bbf] underline">explora tus archivos</span>
              </p>
              <p className="text-xs text-gray-400 mt-1">Soporta formatos .xlsx, .xls o .csv (Max. 20MB)</p>
            </div>
            <div className="inline-flex items-center gap-2 bg-gray-100 text-gray-600 px-3 py-1 rounded-full text-xs font-mono">
              <span>Columnas esperadas: Nombre de Cuenta, ID de Ticket, Prioridad, Tiempo de primera respuesta...</span>
            </div>
          </div>
        )}
      </div>

      {/* Alerts & Messages */}
      {error && (
        <div className="mt-4 p-3 rounded-lg bg-rose-50 border border-rose-200 text-rose-700 text-xs flex items-start gap-2">
          <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
          <div>
            <span className="font-semibold">Error de carga:</span> {error}
          </div>
        </div>
      )}

      {successMsg && (
        <div className="mt-4 p-3 rounded-lg bg-emerald-50 border border-emerald-200 text-emerald-800 text-xs flex items-start gap-2">
          <CheckCircle className="w-4 h-4 shrink-0 mt-0.5 text-emerald-600" />
          <div>{successMsg}</div>
        </div>
      )}
    </div>
  );
}

src/components/ZohoSyncPanel.tsx:
import React, { useState } from "react";
import { RefreshCw, CloudDownload, KeyRound, CheckCircle, AlertCircle, ExternalLink } from "lucide-react";
import { TicketRecord } from "../types";
import {
  fetchZohoReport, getAccessKey, setAccessKey, ZOHO_REPORT_NAME, ZOHO_REPORT_URL, ZohoSyncError,
} from "../utils/zoho";

interface Props {
  onDataLoaded: (tickets: TicketRecord[], fetchedAt: string) => void;
  lastSync: string | null;
  syncing: boolean;
  setSyncing: (b: boolean) => void;
}

const fmt = (iso: string) =>
  new Date(iso).toLocaleString("es-CO", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });

export function ZohoSyncPanel({ onDataLoaded, lastSync, syncing, setSyncing }: Props) {
  const [error, setError] = useState<string | null>(null);
  const [okMsg, setOkMsg] = useState<string | null>(null);
  const [askKey, setAskKey] = useState(false);
  const [keyDraft, setKeyDraft] = useState(getAccessKey());

  const sync = async () => {
    setSyncing(true);
    setError(null);
    setOkMsg(null);
    try {
      const r = await fetchZohoReport();
      onDataLoaded(r.tickets, r.fetchedAt);
      setOkMsg(`Se cargaron ${r.tickets.length} casos desde Zoho Desk${r.source === "tickets-api" ? " (vía API de tickets)" : ""}.`);
      setAskKey(false);
    } catch (e: any) {
      if (e instanceof ZohoSyncError && e.status === 401) {
        setAskKey(true);
        setError("Ingresa la clave de acceso del dashboard para consultar Zoho Desk.");
      } else {
        setError(e?.message || "No se pudo actualizar desde Zoho Desk.");
      }
    } finally {
      setSyncing(false);
    }
  };

  const saveKeyAndSync = (e: React.FormEvent) => {
    e.preventDefault();
    setAccessKey(keyDraft.trim());
    sync();
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-xs">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-start gap-3">
          <div className="p-2 bg-blue-50 text-[#005bbf] rounded-lg"><CloudDownload className="w-5 h-5" /></div>
          <div>
            <h2 className="text-sm font-bold text-gray-900">Datos en vivo desde Zoho Desk</h2>
            <p className="text-xs text-gray-500 mt-0.5">
              Informe:{" "}
              <a href={ZOHO_REPORT_URL} target="_blank" rel="noopener noreferrer" className="text-[#005bbf] font-semibold hover:underline inline-flex items-center gap-0.5">
                {ZOHO_REPORT_NAME} <ExternalLink className="w-3 h-3" />
              </a>
            </p>
            <p className="text-[11px] text-gray-400 mt-0.5">
              {lastSync ? <>Última actualización: <strong className="text-gray-600">{fmt(lastSync)}</strong></> : "Aún no se ha actualizado desde Zoho en este navegador."}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <button
            onClick={() => setAskKey(v => !v)}
            className="p-2 rounded-lg border border-gray-200 text-gray-500 hover:bg-gray-50 cursor-pointer"
            title="Configurar clave de acceso"
          >
            <KeyRound className="w-4 h-4" />
          </button>
          <button
            onClick={sync}
            disabled={syncing}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold text-white bg-[#005bbf] hover:bg-[#004a9c] disabled:opacity-60 cursor-pointer"
          >
            <RefreshCw className={`w-4 h-4 ${syncing ? "animate-spin" : ""}`} />
            {syncing ? "Actualizando..." : "Actualizar desde Zoho Desk"}
          </button>
        </div>
      </div>

      {askKey && (
        <form onSubmit={saveKeyAndSync} className="mt-4 flex flex-col sm:flex-row gap-2">
          <input
            type="password"
            value={keyDraft}
            onChange={e => setKeyDraft(e.target.value)}
            placeholder="Clave de acceso del dashboard"
            autoComplete="off"
            className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-xs focus:ring-[#005bbf] focus:border-[#005bbf]"
          />
          <button type="submit" className="px-3 py-2 rounded-lg text-xs font-semibold text-[#005bbf] bg-[#005bbf]/10 hover:bg-[#005bbf]/20 cursor-pointer">
            Guardar y actualizar
          </button>
        </form>
      )}

      {error && (
        <div className="mt-3 p-2.5 rounded-lg bg-rose-50 border border-rose-200 text-rose-700 text-xs flex items-start gap-2">
          <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" /> <span>{error}</span>
        </div>
      )}
      {okMsg && !error && (
        <div className="mt-3 p-2.5 rounded-lg bg-emerald-50 border border-emerald-200 text-emerald-800 text-xs flex items-start gap-2">
          <CheckCircle className="w-4 h-4 shrink-0 mt-0.5 text-emerald-600" /> <span>{okMsg}</span>
        </div>
      )}
    </div>
  );
}

